def read_input_file(path, prog):
    """Read file at path (bytes), decode as utf-8 with replace, normalize \r\n->\n, \r->\n. Returns (content_str, error_msg, exit_code). Handles '-' as file not found (open -)."""
    if path=="-":
        return (None, f'{prog}: error: open -: no such file or directory\n', 1)
