        with open(path, "rb") as f:
            data=f.read()
    except FileNotFoundError:
        # Should not happen (already validated via stat at parse time, except '-'? Actually '-' bypasses validation, handled above. For other files, stat succeeded, but open could still fail (e.g., permission, race)? Handle.
